<# Holt den Werkzeugkasten. Git-Repos werden nur per Fast-Forward aktualisiert, sonst wird das oeffentliche ZIP geladen. #>
[CmdletBinding()] param()
$ErrorActionPreference = 'Stop'; $root = Split-Path $PSScriptRoot -Parent; $betrieb = Join-Path $root 'betrieb'; New-Item -ItemType Directory -Force $betrieb | Out-Null; $stand = Join-Path $betrieb 'stand.txt'; $alt = if (Test-Path $stand) { (Get-Content $stand -First 1).Split(' ')[0] } else { 'unbekannt' }
if ((Test-Path (Join-Path $root '.git')) -and (Get-Command git -ErrorAction SilentlyContinue)) { $alt = (& git -C $root rev-parse --short HEAD); & git -C $root pull --ff-only; if ($LASTEXITCODE) { exit $LASTEXITCODE }; $neu = (& git -C $root rev-parse --short HEAD); Set-Content $stand "$neu $(Get-Date -Format 'dd.MM.yyyy HH:mm') git"; Write-Output "Stand vorher: $alt"; Write-Output "Stand jetzt:  $neu"; if ($alt -ne $neu) { & git -C $root diff --name-status $alt $neu } else { Write-Output 'Keine Änderungen.' }; exit 0 }
try { $tmp = Join-Path ([IO.Path]::GetTempPath()) "maschinenraum-$([guid]::NewGuid())"; New-Item -ItemType Directory $tmp | Out-Null; Invoke-WebRequest 'https://github.com/philip-macht-ki/maschinenraum/archive/main.zip' -OutFile "$tmp\archiv.zip"; Expand-Archive "$tmp\archiv.zip" $tmp -Force; $quelle = Get-ChildItem $tmp -Directory | Where-Object Name -like 'maschinenraum-*' | Select-Object -First 1; Get-ChildItem $quelle.FullName -Force | Where-Object Name -ne 'betrieb' | Copy-Item -Destination $root -Recurse -Force; Set-Content $stand "main $(Get-Date -Format 'dd.MM.yyyy HH:mm') archiv"; Write-Output "Werkzeugkasten aktualisiert: $root" } finally { if ($tmp) { Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue } }
